<template>
  <main class="chat-shell">
    <section class="chat-intro"><div><span class="eyebrow">CINEAGENT · 电影推荐实验室</span><h1>把想看的电影，说具体一点。</h1><p>真实片库 · 模型排序 · 可追溯的偏好记忆</p></div><a href="/" class="home-link">返回首页推荐 ↗</a></section>
    <div class="workspace">
      <section class="conversation">
        <div class="toolbar"><label>运行模式 <select v-model="mode"><option value="offline">离线规则 · 不调用 API</option><option value="deepseek" :disabled="!status.provider_configured">DeepSeek · 真实工具调用</option></select></label><button @click="newConversation" :disabled="busy">新建会话</button></div>
        <div class="notice">标题与类型文本召回；海报关联与使用许可尚未完成核验，本页使用文字卡片。<span v-if="mode==='deepseek'">本轮将发送需求、相关偏好摘要和必要工具结果到 DeepSeek 官方接口。</span></div>
        <div v-if="!turns.length" class="empty"><div class="empty-symbol">◉</div><h2>今晚想看什么？</h2><p>类型、片长和明确排除项，都能影响实际候选与排序。</p><button v-for="sample in samples" :key="sample" @click="text=sample">{{ sample }} ↗</button></div>
        <div v-for="(turn,index) in turns" :key="index" class="turn">
          <div class="user-message">{{ turn.text }}</div>
          <div class="answer" :data-request-id="turn.response.request_id" :data-render-ms="turn.client_elapsed_ms"><div class="answer-meta">{{ turn.response.mode==='deepseek_tools'?'DeepSeek 工具循环':turn.response.mode==='clarification'?'需要澄清':'离线推荐' }} · {{ turn.response.elapsed_ms }} ms · 候选 {{ turn.response.eligible_count }}</div><p class="client-metrics">浏览器发送至结果渲染 {{ turn.client_elapsed_ms }} ms · 输入 {{ turn.response.token_usage?.input ?? 0 }} / 输出 {{ turn.response.token_usage?.output ?? 0 }} tokens · 保守费用 ${{ turn.response.token_usage?.conservative_successful_calls_usd ?? 0 }}</p><p>{{ turn.response.message }}</p><p class="warning" v-for="warning in turn.response.warnings" :key="warning">{{ warning }}</p><p class="warning" v-if="turn.response.degradation.length">已降级：{{ turn.response.degradation.join('；') }}</p>
            <div v-if="turn.response.relaxation_suggestions?.length" class="warning"><p>以下方案需要你确认，当前条件尚未改变：</p><button v-for="option in turn.response.relaxation_suggestions" :key="option.message" @click="text=option.message" :disabled="busy || turn!==turns[turns.length-1]">{{ option.label }} · {{ option.eligible_count }} 部候选（填入输入框）</button></div>
            <div class="movie-grid"><article v-for="(movie,n) in turn.response.items" :key="movie.movie_id" class="movie"><a :href="'/movie/'+movie.movie_id"><div class="text-cover"><span>FILM</span><strong>{{ movie.movie_id }}</strong><small>{{ movie.year }}</small></div></a><div><span class="movie-number">{{ n+1 }} / #{{ movie.movie_id }}</span><a :href="'/movie/'+movie.movie_id"><h3>{{ movie.title }}</h3></a><p>{{ movie.reason }}</p><small>{{ movie.ranking_strategy }} · {{ movie.score.toFixed(3) }}</small><div class="feedback"><button @click="feedback(movie,turn.response,'seen')" :disabled="busy || turn!==turns[turns.length-1]">看过了</button><button @click="feedback(movie,turn.response,'dislike')" :disabled="busy || turn!==turns[turns.length-1]">不感兴趣</button></div></div></article></div>
            <details><summary>查看约束、来源与工具轨迹</summary><pre>{{ JSON.stringify({constraints:turn.response.constraints,summary:turn.response.summary,tools:turn.response.trace,evidence:turn.response.evidence_checks,versions:turn.response.versions},null,2) }}</pre></details>
          </div>
        </div>
        <form class="composer" @submit.prevent="send"><label class="sr-only" for="movie-request">电影需求</label><textarea id="movie-request" v-model="text" maxlength="4000" rows="3" placeholder="例如：想看悬疑电影，不要恐怖片，两小时以内。" :disabled="busy"></textarea><div><span>{{ busy?'正在筛选和排序…':'支持：第一部看过了，换类似的，但不要同一个导演。' }}</span><button type="submit" :disabled="busy || !text.trim()">{{ busy?'处理中…':'发送需求 →' }}</button></div></form>
        <p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="feedbackMessage" role="status" class="feedback-message">{{ feedbackMessage }}</p>
      </section>
      <aside><section class="side-card"><h2>偏好记忆</h2><label class="toggle"><input type="checkbox" v-model="useMemory" /> 使用长期偏好</label><p>只有“记住 / 以后 / 长期”等明确表达才保存。当前需求仅限本次会话。</p><div v-if="!preferences.length" class="muted">还没有长期偏好。试试“以后记住我不喜欢恐怖片”。</div><article v-for="pref in preferences" :key="pref.id" class="preference"><strong>{{ pref.key==='exclude_genres'?'排除':'偏爱' }} {{ pref.value }}</strong><small>来源：第 {{ pref.source_turn }} 轮 · {{ new Date(pref.created_at).toLocaleString() }}</small><div><button @click="revoke(pref)">撤销</button><button @click="remove(pref)">删除</button></div></article></section>
      <section class="side-card"><h2>上下文与预算</h2><label class="toggle"><input type="checkbox" v-model="compressHistory" /> 结构化摘要 + 最近四轮</label><p>摘要保留当前约束、排除项与原文位置；原始对话保留在本机会话表。</p><dl><dt>接口调用</dt><dd>{{ status.requests_used || 0 }} / {{ status.request_limit || 30 }}</dd><dt>保守费用估算</dt><dd>${{ status.conservative_cost_usd || 0 }} / $0.10</dd><dt>内容通道</dt><dd>标题 + 类型 TF-IDF</dd><dt>模型版本</dt><dd>rec-v1 / DeepFM</dd></dl><p class="muted">试跑达到请求、token 或费用限额后自动回退本地推荐。</p></section></aside>
    </div>
  </main>
</template>
<script setup>
import {ref,onMounted,nextTick} from 'vue'
const text=ref(''),mode=ref('offline'),busy=ref(false),error=ref(''),feedbackMessage=ref(''),turns=ref([]),conversation=ref(null),preferences=ref([]),status=ref({}),useMemory=ref(true),compressHistory=ref(true)
const samples=['想看悬疑电影，不要恐怖片，最好两小时以内。','想看科幻电影，不要恐怖片。','以后记住我不喜欢恐怖片。']
let token='',pending=null
async function request(path,body,method){const response=await fetch('/api/chat'+path,{method:method||(body?'POST':'GET'),headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:body?JSON.stringify(body):undefined});let result;try{result=await response.json()}catch{throw new Error('服务暂不可用，请稍后重试。')}if(!response.ok)throw new Error(typeof result.detail==='string'?result.detail:'请求验证失败');return result}
async function refresh(){status.value=await request('/status');if(token)preferences.value=(await request('/preferences')).items}
async function connect(){if(new URLSearchParams(location.search).get('evaluation')==='v4'){token=(await request('/evaluation-guest',{})).access_token;await refresh();return}token=localStorage.getItem('token')||localStorage.getItem('cineagent_guest_token')||'';if(!token){const guest=await request('/guest',{});token=guest.access_token;localStorage.setItem('cineagent_guest_token',token)}await refresh()}
async function send(){if(busy.value||!text.value.trim())return;busy.value=true;error.value='';feedbackMessage.value='';const sent=text.value;const body=pending && pending.message===sent && pending.conversation_id===conversation.value && pending.mode===mode.value && pending.use_memory===useMemory.value && pending.compress_history===compressHistory.value ? pending : {request_id:crypto.randomUUID(),conversation_id:conversation.value,message:sent,mode:mode.value,use_memory:useMemory.value,compress_history:compressHistory.value};pending=body;const clientStarted=performance.now();try{const result=await request('/message',body);pending=null;conversation.value=result.conversation_id;turns.value.push({text:sent,response:result,client_elapsed_ms:null});text.value='';await nextTick();turns.value[turns.value.length-1].client_elapsed_ms=Math.round((performance.now()-clientStarted)*100)/100;await refresh()}catch(e){error.value=e.message}finally{busy.value=false}}
function newConversation(){pending=null;conversation.value=null;turns.value=[];error.value='';feedbackMessage.value=''}
async function feedback(movie,response,kind){try{await request('/feedback',{request_id:crypto.randomUUID(),conversation_id:response.conversation_id,movie_id:movie.movie_id,kind});feedbackMessage.value='已记录，下次推荐将排除：'+movie.title}catch(e){error.value=e.message}}
async function remove(pref){try{await request('/preferences/'+pref.id,null,'DELETE');await refresh()}catch(e){error.value=e.message}}
async function revoke(pref){try{await request('/preferences/'+pref.id+'/revoke',{});await refresh()}catch(e){error.value=e.message}}
function imageError(e){e.target.style.visibility='hidden'}
onMounted(async()=>{try{await connect()}catch(e){error.value=e.message}})
</script>
<style scoped>
.chat-shell{max-width:1440px;margin:auto;padding:116px 44px 60px;color:#182936;background:#f6f8fa;min-height:100vh}.chat-intro{display:flex;justify-content:space-between;align-items:center;margin-bottom:30px}.eyebrow{font-size:12px;letter-spacing:2px;color:#387c82;font-weight:700}.chat-intro h1{font-size:34px;letter-spacing:-1px;margin:12px 0}.chat-intro p,.notice{color:#60717e}.home-link{color:#286d74;font-size:14px}.workspace{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:24px}.conversation,.side-card{background:white;border:1px solid #dfe6eb;border-radius:16px}.conversation{padding:24px}.toolbar{display:flex;justify-content:space-between;gap:12px;font-size:13px}.toolbar select{padding:8px;border:1px solid #d9e2e8;border-radius:8px;margin-left:8px}button{cursor:pointer}.toolbar button,.preference button{color:#28747a}.notice{font-size:12px;line-height:1.8;background:#f0f6f7;padding:12px;border-radius:8px;margin-top:18px}.notice span{display:block}.empty{text-align:center;padding:40px 20px}.empty-symbol{color:#347e85;font-size:42px}.empty h2{font-size:24px;margin:12px}.empty p{color:#788792;margin:12px 0 24px}.empty button{display:block;text-align:left;border:1px solid #e0e7ec;border-radius:10px;margin:10px auto;padding:14px 18px;font-size:13px;max-width:500px;width:100%;color:#345768}.user-message{background:#e7f1f3;border-radius:14px 14px 0 14px;padding:14px 18px;margin:24px 0 18px 15%;white-space:pre-wrap}.answer-meta{font-size:12px;color:#56818a;margin-bottom:10px}.answer>p{font-size:14px;margin:8px 0}.warning{color:#9b671c;background:#fff8e8;padding:10px;border-radius:6px}.movie-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:20px 0}.movie{display:flex;gap:12px;border:1px solid #e2e9ed;border-radius:10px;padding:12px;min-width:0}.movie>a{width:72px;flex-shrink:0;background:#edf1f4;border-radius:5px;overflow:hidden}.text-cover{width:72px;min-height:108px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;background:linear-gradient(145deg,#244957,#6b8d94);color:white}.text-cover span{font-size:9px;letter-spacing:3px}.text-cover strong{font-size:18px}.text-cover small{color:#d5e3e8!important}.movie img{width:72px;height:108px;object-fit:cover}.movie-number{font-size:10px;color:#6c8794}.movie h3{font-size:14px;font-weight:700;line-height:1.4;margin:5px 0}.movie p{font-size:11px;color:#647884;line-height:1.6}.movie small{font-size:10px;color:#8a9aa4}.feedback{display:flex;gap:12px;margin-top:10px}.feedback button{font-size:11px;color:#24727a}.feedback button:disabled{opacity:.4;cursor:default}details{margin:15px 0;font-size:12px;color:#64808a}summary{cursor:pointer}pre{white-space:pre-wrap;max-height:320px;overflow:auto;background:#f3f6f8;padding:12px;font-size:11px}.composer{border:1px solid #b5cbd2;border-radius:12px;overflow:hidden;margin-top:24px}.composer textarea{display:block;width:100%;resize:vertical;padding:15px;border:0;outline:0;font-size:14px}.composer>div{display:flex;justify-content:space-between;align-items:center;padding:10px 12px;background:#f8fafb;gap:12px}.composer span{font-size:10px;color:#8395a0}.composer button{background:#256f76;color:white;padding:10px 16px;border-radius:8px;font-size:13px;white-space:nowrap}.composer button:disabled{opacity:.5}.side-card{padding:22px;margin-bottom:20px}.side-card h2{font-weight:700;font-size:16px;margin-bottom:16px}.toggle{display:flex;gap:9px;align-items:center;font-size:13px}.side-card p,.muted{font-size:12px;color:#7d8f9c;line-height:1.8;margin:14px 0}.preference{border-top:1px solid #e5ecf0;padding:14px 0}.preference strong{font-size:13px}.preference small{display:block;font-size:10px;color:#8b9ca7;margin:6px 0}.preference div{display:flex;gap:15px;font-size:11px}dl{display:grid;grid-template-columns:1fr 1fr;font-size:11px;gap:12px}dt{color:#7f939f}dd{text-align:right}.error{color:#a83e3e;background:#fff1f1;padding:12px;margin-top:10px}.feedback-message{font-size:12px;color:#28747a;margin-top:12px}@media(max-width:1050px){.workspace{grid-template-columns:1fr}.chat-shell{padding:105px 18px 35px}.chat-intro h1{font-size:26px}.home-link{display:none}aside{display:grid;grid-template-columns:1fr 1fr;gap:16px}}@media(max-width:650px){.movie-grid{grid-template-columns:1fr}aside{display:block}.toolbar{flex-wrap:wrap}.chat-intro h1{font-size:23px}.conversation{padding:16px}.composer span{display:none}}
</style>



